/**
 * Citadel theme — tactical, luminous, HUD-inspired.
 * Visual identity only; no Citadel-specific component forks.
 *
 * Font stacks reference Hanken Grotesk, Plus Jakarta Sans, and Geist with
 * system fallbacks. Font files are application-owned — load via HTML <link> or
 * approved packages (see docs/font-loading.md). This file must not contain
 * remote @import statements (Tailwind 4 / Lightning CSS consumers break on them).
 * Builds and smoke tests must not require a remote font provider.
 */

[data-theme="citadel"] {
  /* Page and surfaces — field #051A33, surface #0C233C, surface-2 #102B49 */
  --background: 0.216 0.053 254.7;
  --foreground: 0.957 0.017 248;

  --surface-subtle: 0.227 0.051 254.8;
  --surface: 0.252 0.055 252.2;
  --surface-raised: 0.282 0.062 252.2;
  --surface-overlay: 0.195 0.045 254;

  /* Borders and focus */
  --border: 0.331 0.061 251.6;
  --border-strong: 0.733 0.149 231.4;
  --focus-ring: 0.733 0.149 231.4;

  /* Primary — Pacific #00B8F5; CTA ink ~#04253A */
  --primary: 0.733 0.149 231.4;
  --primary-hover: 0.664 0.134 231.2;
  --primary-active: 0.593 0.119 230.8;
  --primary-foreground: 0.247 0.055 244.2;

  /* Secondary — body text role ~#C8D3E0 */
  --secondary: 0.29 0.067 253.6;
  --secondary-hover: 0.328 0.074 253.6;
  --secondary-active: 0.366 0.082 253.5;
  --secondary-foreground: 0.863 0.019 251.6;

  /* Accent — Cobalt #1E49E2 */
  --accent: 0.482 0.237 265.8;
  --accent-foreground: 0.957 0.017 248;

  /* Muted — #6B7C90 */
  --muted: 0.28 0.054 253.1;
  --muted-foreground: 0.579 0.035 251.9;

  /* Status — success #4ADE80, warning #FFC857, critical #FF6B6B */
  --success: 0.8 0.182 151.8;
  --success-foreground: 0.195 0.045 254;

  --warning: 0.87 0.144 85.5;
  --warning-foreground: 0.195 0.045 254;

  --danger: 0.712 0.181 22.8;
  --danger-foreground: 0.195 0.045 254;

  --information: 0.733 0.149 231.4;
  --information-foreground: 0.247 0.055 244.2;

  /* Shape */
  --radius-control: 0;
  --radius-card: 0;
  --radius-panel: 0;
  --radius-overlay: 0.25rem;
  --radius-pill: 9999px;

  --border-width-control: 1px;
  --border-width-panel: 1px;

  /* Typography — labels use Geist (sans) per live Citadel HUD */
  --font-display: "Hanken Grotesk", "Plus Jakarta Sans", system-ui, sans-serif;
  --font-body: "Hanken Grotesk", "Plus Jakarta Sans", system-ui, -apple-system, sans-serif;
  --font-mono: "Geist", "Geist Mono", "IBM Plex Mono", ui-monospace, monospace;
  --font-data: var(--font-mono);

  --font-weight-heading: 800;
  --font-weight-label: 600;
  --font-weight-body: 400;

  --tracking-heading: -0.02em;
  --tracking-label: 0.2em;
  --text-transform-label: uppercase;

  /* Controls */
  --control-height-sm: 2.25rem;
  --control-height-md: 2.75rem;
  --control-height-lg: 4rem;

  --control-padding-inline-sm: 0.75rem;
  --control-padding-inline-md: 1rem;
  --control-padding-inline-lg: 1.5rem;

  /* Panels and spacing */
  --panel-padding-sm: 1rem;
  --panel-padding-md: 1.5rem;
  --panel-padding-lg: 1.75rem;

  --section-gap: 1.25rem;
  --content-max-width: 72rem;

  /* Shadows */
  --shadow-control: 0 0 0 1px oklch(0.733 0.149 231.4 / 0.24), 0 4px 14px rgb(0 0 0 / 0.38);

  --shadow-card: 0 0 0 1px oklch(0.733 0.149 231.4 / 0.18), 0 12px 32px rgb(0 0 0 / 0.34);

  --shadow-panel-depth: 0 12px 32px rgb(0 0 0 / 0.34);
  --shadow-panel-overlay-depth: 0 24px 64px rgb(0 0 0 / 0.55);

  --shadow-overlay: 0 0 0 1px oklch(0.733 0.149 231.4 / 0.3), 0 24px 64px rgb(0 0 0 / 0.55);

  --shadow-focus: 0 0 0 2px oklch(var(--background)), 0 0 0 4px oklch(var(--focus-ring) / 0.75);

  /* Motion — --easing-out from audit */
  --duration-fast: 100ms;
  --duration-standard: 200ms;
  --duration-emphasis: 320ms;

  --ease-standard: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-emphasis: cubic-bezier(0.65, 0, 0.35, 1);

  --press-scale: 0.98;
  --hover-translate: -1px;

  /* Shell */
  --gs-shell-gradient:
    radial-gradient(ellipse at 50% -10%, oklch(0.733 0.149 231.4 / 0.12), transparent 42%),
    linear-gradient(180deg, oklch(0.216 0.053 254.7), oklch(0.183 0.043 253.1));

  /* Extension tokens — consumed by theme-scoped component/shell rules */
  --shell-grid-color: 0.733 0.149 231.4;
  --shell-grid-dot-alpha: 0.18;
  --shell-grid-size-participant: 32px;
  --shell-grid-size-display: 40px;
  --shell-grid-line-alpha: 0.04;
  --shell-scanline-alpha: 0.03;

  --shell-vignette: radial-gradient(
    ellipse at center,
    transparent 0%,
    transparent 50%,
    oklch(0.216 0.053 254.7 / 0.28) 88%,
    oklch(0.216 0.053 254.7 / 0.55) 100%
  );

  --panel-surface-alpha: 0.7;
  --panel-border-alpha: 0.15;
  --panel-blur: 12px;

  --input-surface-alpha: 0.6;
  --input-border-alpha: 0.25;
  --input-border-hover-alpha: 0.4;

  --scope-corner-size-sm: 10px;
  --scope-corner-size-md: 12px;
  --scope-corner-size-lg: 16px;
  --scope-corner-width: 2px;
  --scope-corner-offset: -1px;
  --scope-corner-color: oklch(var(--border-strong));

  --hairline-alpha: 0.3;
  --overlay-scrim-alpha: 0.72;

  /* Glow roles — pacific / cobalt / warning / critical */
  --glow-pacific: 0 0 12px oklch(0.733 0.149 231.4 / 0.4);
  --glow-pacific-strong: 0 0 24px oklch(0.733 0.149 231.4 / 0.6);
  --glow-cobalt: 0 0 12px oklch(0.482 0.237 265.8 / 0.4);
  --glow-warning: 0 0 12px oklch(0.87 0.144 85.5 / 0.5);
  --glow-danger: 0 0 12px oklch(0.712 0.181 22.8 / 0.5);
  /* Canonical public critical role aliases danger; app --glow-critical maps here */
  --glow-critical: var(--glow-danger);
  /* Back-compat aliases used by existing rules */
  --glow-emphasis: var(--glow-cobalt);
  --glow-information: var(--glow-pacific);

  --action-bar-pad-top: 2rem;
  --action-bar-safe-bottom: max(1.5rem, env(safe-area-inset-bottom));
  --action-bar-bleed: linear-gradient(
    to top,
    oklch(0.216 0.053 254.7 / 0.95),
    oklch(0.216 0.053 254.7 / 0.5) 70%,
    transparent
  );
}

/* Shared-display density must not soften Citadel geometry */
[data-theme="citadel"][data-context="shared-display"] {
  --radius-panel: 0;
  --radius-control: 0;
  --radius-card: 0;
}

/* -------------------------------------------------------------------------- */
/* Scope corners — four L-brackets via layered backgrounds on ::before        */
/* -------------------------------------------------------------------------- */

[data-theme="citadel"] .gs-panel,
[data-theme="citadel"] .gs-card,
[data-theme="citadel"] .gs-button[data-emphasis="strong"] {
  --scope-corner-size: var(--scope-corner-size-md);
  position: relative;
  overflow: visible;
}

[data-theme="citadel"] .gs-button[data-emphasis="strong"][data-size="sm"],
[data-theme="citadel"] .gs-panel[data-padding="sm"] {
  --scope-corner-size: var(--scope-corner-size-sm);
}

[data-theme="citadel"] .gs-button[data-emphasis="strong"][data-size="lg"],
[data-theme="citadel"] .gs-panel[data-padding="lg"] {
  --scope-corner-size: var(--scope-corner-size-lg);
}

[data-theme="citadel"] .gs-panel::before,
[data-theme="citadel"] .gs-card::before,
[data-theme="citadel"] .gs-button[data-emphasis="strong"]::before {
  content: "";
  position: absolute;
  inset: var(--scope-corner-offset);
  pointer-events: none;
  z-index: 1;
  background:
    linear-gradient(var(--scope-corner-color), var(--scope-corner-color)) top left /
      var(--scope-corner-size) var(--scope-corner-width) no-repeat,
    linear-gradient(var(--scope-corner-color), var(--scope-corner-color)) top left /
      var(--scope-corner-width) var(--scope-corner-size) no-repeat,
    linear-gradient(var(--scope-corner-color), var(--scope-corner-color)) top right /
      var(--scope-corner-size) var(--scope-corner-width) no-repeat,
    linear-gradient(var(--scope-corner-color), var(--scope-corner-color)) top right /
      var(--scope-corner-width) var(--scope-corner-size) no-repeat,
    linear-gradient(var(--scope-corner-color), var(--scope-corner-color)) bottom left /
      var(--scope-corner-size) var(--scope-corner-width) no-repeat,
    linear-gradient(var(--scope-corner-color), var(--scope-corner-color)) bottom left /
      var(--scope-corner-width) var(--scope-corner-size) no-repeat,
    linear-gradient(var(--scope-corner-color), var(--scope-corner-color)) bottom right /
      var(--scope-corner-size) var(--scope-corner-width) no-repeat,
    linear-gradient(var(--scope-corner-color), var(--scope-corner-color)) bottom right /
      var(--scope-corner-width) var(--scope-corner-size) no-repeat;
}

[data-theme="citadel"]
  .gs-button[data-emphasis="strong"]:not(:disabled):not([aria-disabled="true"]) {
  --scope-corner-color: oklch(var(--primary-foreground));
}

[data-theme="citadel"] .gs-button[data-emphasis="strong"]:disabled::before,
[data-theme="citadel"] .gs-button[data-emphasis="strong"][aria-disabled="true"]::before {
  --scope-corner-color: oklch(var(--border-strong));
  opacity: 0.55;
}

/* -------------------------------------------------------------------------- */
/* Button — sticky CTA language via emphasis=strong                           */
/* -------------------------------------------------------------------------- */

[data-theme="citadel"] .gs-button {
  border-radius: var(--radius-control);
  font-family: var(--font-mono);
  font-weight: var(--font-weight-label);
  letter-spacing: var(--tracking-label);
  text-transform: var(--text-transform-label);
}

[data-theme="citadel"]
  .gs-button[data-emphasis="strong"]:not(:disabled):not([aria-disabled="true"]) {
  box-shadow: var(--glow-pacific-strong);
}

[data-theme="citadel"] .gs-button[data-emphasis="strong"]:disabled,
[data-theme="citadel"] .gs-button[data-emphasis="strong"][aria-disabled="true"] {
  background: transparent;
  color: oklch(var(--muted-foreground));
  border: 1px solid oklch(var(--border-strong));
  box-shadow: none;
  opacity: 1;
}

@media (prefers-reduced-motion: reduce) {
  [data-theme="citadel"] .gs-button {
    --press-scale: 1;
  }

  [data-theme="citadel"]
    .gs-button[data-emphasis="strong"]:not(:disabled):not([aria-disabled="true"]) {
    box-shadow: none;
  }
}

/* -------------------------------------------------------------------------- */
/* Input / Textarea / Label                                                    */
/* -------------------------------------------------------------------------- */

[data-theme="citadel"] .gs-input {
  background: oklch(var(--background) / var(--input-surface-alpha));
  border-color: oklch(var(--border-strong) / var(--input-border-alpha));
  color: oklch(var(--foreground));
  box-shadow: none;
  border-radius: var(--radius-control);
  font-family: var(--font-body);
}

[data-theme="citadel"] .gs-input:hover:not(:disabled):not([aria-invalid="true"]) {
  border-color: oklch(var(--border-strong) / var(--input-border-hover-alpha));
}

[data-theme="citadel"] .gs-input:focus-visible {
  border-color: oklch(var(--focus-ring));
  box-shadow: none;
  outline: none;
}

[data-theme="citadel"] .gs-input::placeholder {
  color: oklch(var(--muted-foreground));
}

[data-theme="citadel"] .gs-input[aria-invalid="true"] {
  border-color: oklch(var(--danger));
}

[data-theme="citadel"] .gs-input[aria-invalid="true"]:focus-visible {
  box-shadow: none;
  border-color: oklch(var(--danger));
}

[data-theme="citadel"] .gs-label {
  font-family: var(--font-mono);
  font-weight: var(--font-weight-label);
  letter-spacing: var(--tracking-label);
  text-transform: var(--text-transform-label);
}

[data-theme="citadel"] .gs-eyebrow {
  color: oklch(var(--primary));
}

/* -------------------------------------------------------------------------- */
/* Forms — checkbox, radio, switch, select, slider, tabs, accordion           */
/* -------------------------------------------------------------------------- */

[data-theme="citadel"] .gs-checkbox,
[data-theme="citadel"] .gs-radio {
  border-color: oklch(var(--border-strong) / 0.45);
  background: oklch(var(--background) / var(--input-surface-alpha));
}

[data-theme="citadel"] .gs-checkbox {
  border-radius: var(--radius-control);
}

[data-theme="citadel"] .gs-radio {
  border-radius: 9999px;
}

[data-theme="citadel"] .gs-checkbox[data-state="checked"],
[data-theme="citadel"] .gs-radio[data-state="checked"] {
  border-color: oklch(var(--primary));
  background: oklch(var(--primary));
  color: oklch(var(--primary-foreground));
  box-shadow: var(--glow-pacific);
}

[data-theme="citadel"] .gs-switch {
  border-radius: var(--radius-control);
  background: oklch(var(--muted));
}

[data-theme="citadel"] .gs-switch[data-state="checked"] {
  background: oklch(var(--primary));
  box-shadow: var(--glow-pacific);
}

[data-theme="citadel"] .gs-select-trigger {
  background: oklch(var(--background) / var(--input-surface-alpha));
  border-color: oklch(var(--border-strong) / var(--input-border-alpha));
  border-radius: var(--radius-control);
  color: oklch(var(--foreground));
  box-shadow: none;
}

[data-theme="citadel"] .gs-select-trigger:focus,
[data-theme="citadel"] .gs-select-trigger:focus-visible {
  border-color: oklch(var(--focus-ring));
  box-shadow: none;
  outline: none;
}

[data-theme="citadel"] .gs-select-content,
[data-theme="citadel"] .gs-popover-content,
[data-theme="citadel"] .gs-dropdown-content {
  background: oklch(var(--surface-raised));
  border-color: oklch(var(--border-strong) / 0.28);
  border-radius: var(--radius-control);
  box-shadow: var(--shadow-overlay);
}

[data-theme="citadel"] .gs-slider-track {
  border-radius: 0;
  background: oklch(var(--muted));
}

[data-theme="citadel"] .gs-slider-range {
  background: oklch(var(--primary));
}

[data-theme="citadel"] .gs-slider-thumb {
  border-radius: 0;
  border-color: oklch(var(--primary));
  background: oklch(var(--background));
  box-shadow: var(--glow-pacific);
}

[data-theme="citadel"] .gs-tabs-list {
  border-radius: var(--radius-control);
  background: oklch(var(--surface) / var(--panel-surface-alpha));
  border: 1px solid oklch(var(--border-strong) / 0.18);
}

[data-theme="citadel"] .gs-tabs-trigger {
  border-radius: var(--radius-control);
  font-family: var(--font-mono);
  font-weight: var(--font-weight-label);
  letter-spacing: var(--tracking-label);
  text-transform: uppercase;
}

[data-theme="citadel"] .gs-tabs-trigger[data-state="active"] {
  background: oklch(var(--primary) / 0.12);
  color: oklch(var(--primary));
  box-shadow: inset 0 -2px 0 oklch(var(--primary));
}

[data-theme="citadel"] .gs-accordion-item {
  border-color: oklch(var(--border-strong) / 0.2);
}

[data-theme="citadel"] .gs-accordion-trigger {
  font-family: var(--font-mono);
  font-weight: var(--font-weight-label);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* -------------------------------------------------------------------------- */
/* Panel / Card / Separator / Empty / Table                                   */
/* -------------------------------------------------------------------------- */

[data-theme="citadel"] .gs-panel {
  background: oklch(var(--surface) / var(--panel-surface-alpha));
  border: var(--border-width-panel) solid oklch(var(--border-strong) / var(--panel-border-alpha));
  border-radius: var(--radius-panel);
  backdrop-filter: blur(var(--panel-blur));
  box-shadow: none;
}

[data-theme="citadel"] .gs-panel[data-elevation="raised"] {
  background: oklch(var(--surface-raised) / 0.9);
  box-shadow:
    var(--shadow-panel-depth),
    inset 0 1px 0 oklch(var(--foreground) / 0.04);
}

[data-theme="citadel"] .gs-panel[data-elevation="overlay"] {
  box-shadow: var(--shadow-panel-overlay-depth);
}

[data-theme="citadel"] .gs-panel[data-emphasis="strong"] {
  border-color: oklch(var(--border-strong) / var(--panel-border-alpha));
  box-shadow: var(--shadow-panel-depth), var(--glow-cobalt);
}

[data-theme="citadel"] .gs-panel > .gs-panel-content {
  position: relative;
  z-index: 0;
  min-width: 0;
}

[data-theme="citadel"] .gs-card {
  background: oklch(var(--surface) / var(--panel-surface-alpha));
  border: 1px solid oklch(var(--border-strong) / var(--panel-border-alpha));
  border-radius: var(--radius-card);
  backdrop-filter: blur(var(--panel-blur));
  box-shadow: none;
}

[data-theme="citadel"] .gs-separator {
  background: oklch(var(--border-strong) / var(--hairline-alpha));
}

[data-theme="citadel"] .gs-separator[data-treatment="hairline"] {
  background: oklch(var(--border-strong) / var(--hairline-alpha));
}

[data-theme="citadel"] .gs-eyebrow-dotted {
  color: oklch(var(--primary));
  font-family: var(--font-mono);
  letter-spacing: var(--tracking-label);
  text-transform: uppercase;
}

[data-theme="citadel"] .gs-countdown[data-intent="critical"],
[data-theme="citadel"] .gs-countdown[data-state="expired"] {
  color: oklch(var(--danger));
  text-shadow: var(--glow-critical);
}

[data-theme="citadel"]
  .gs-phase-directive[data-treatment="panel"][data-intent="critical"]
  .gs-panel,
[data-theme="citadel"] .gs-outcome-summary[data-intent="critical"] .gs-panel {
  --scope-corner-color: oklch(var(--danger));
  box-shadow: var(--glow-critical);
}

[data-theme="citadel"] .gs-phase-directive[data-treatment="panel"][data-intent="warning"] .gs-panel,
[data-theme="citadel"] .gs-outcome-summary[data-intent="warning"] .gs-panel {
  --scope-corner-color: oklch(var(--warning));
  box-shadow: var(--glow-warning);
}

[data-theme="citadel"]
  .gs-phase-directive[data-treatment="panel"][data-intent="information"]
  .gs-panel,
[data-theme="citadel"] .gs-outcome-summary[data-intent="information"] .gs-panel {
  --scope-corner-color: oklch(var(--primary));
  box-shadow: var(--glow-information);
}

[data-theme="citadel"] .gs-outcome-summary[data-intent="success"] .gs-panel {
  --scope-corner-color: oklch(var(--success));
}

[data-theme="citadel"] .gs-sticky-action-bar {
  background-image: var(--action-bar-bleed);
}

[data-theme="citadel"] .gs-empty {
  border-color: oklch(var(--border-strong) / 0.25);
  border-radius: var(--radius-panel);
  background: oklch(var(--surface) / 0.4);
}

[data-theme="citadel"] .gs-table {
  border-collapse: collapse;
}

[data-theme="citadel"] .gs-table th {
  font-family: var(--font-mono);
  font-weight: var(--font-weight-label);
  letter-spacing: var(--tracking-label);
  text-transform: uppercase;
  color: oklch(var(--muted-foreground));
  border-bottom-color: oklch(var(--border-strong) / 0.25);
}

[data-theme="citadel"] .gs-table td {
  border-bottom-color: oklch(var(--border) / 0.8);
}

/* -------------------------------------------------------------------------- */
/* Badge — classified chip                                                    */
/* -------------------------------------------------------------------------- */

[data-theme="citadel"] .gs-badge {
  font-family: var(--font-mono);
  font-weight: var(--font-weight-label);
  letter-spacing: var(--tracking-label);
  text-transform: uppercase;
  border-radius: 0.125rem;
  padding-inline: 0.5rem;
  padding-block: 0.125rem;
}

[data-theme="citadel"] .gs-badge[data-intent="information"][data-treatment="outlined"] {
  color: oklch(var(--information));
  border-color: oklch(var(--information));
  background: oklch(var(--information) / 0.08);
}

[data-theme="citadel"] .gs-badge[data-treatment="outlined"] {
  background: transparent;
}

[data-theme="citadel"] .gs-badge[data-treatment="subtle"][data-intent="information"] {
  color: oklch(var(--information));
  background: oklch(var(--information) / 0.12);
  border-color: transparent;
}

/* -------------------------------------------------------------------------- */
/* Alert — validation banner                                                  */
/* -------------------------------------------------------------------------- */

[data-theme="citadel"] .gs-alert {
  background: rgb(0 0 0 / 0.2);
  border-radius: var(--radius-panel);
  border-width: 1px;
}

[data-theme="citadel"] .gs-alert[data-intent="information"] {
  border-color: oklch(var(--information));
}

[data-theme="citadel"] .gs-alert[data-intent="success"] {
  border-color: oklch(var(--success));
}

[data-theme="citadel"] .gs-alert[data-intent="warning"] {
  border-color: oklch(var(--warning));
}

[data-theme="citadel"] .gs-alert[data-intent="danger"] {
  border-color: oklch(var(--danger));
}

/* -------------------------------------------------------------------------- */
/* Overlays — dialog / sheet / tooltip / toaster                              */
/* -------------------------------------------------------------------------- */

[data-theme="citadel"] .gs-dialog-overlay {
  background: oklch(var(--background) / var(--overlay-scrim-alpha));
}

[data-theme="citadel"] .gs-dialog-content,
[data-theme="citadel"] .gs-sheet-content {
  background: oklch(var(--surface) / 0.92);
  border-color: oklch(var(--border-strong) / 0.28);
  border-radius: var(--radius-overlay);
  backdrop-filter: blur(var(--panel-blur));
  box-shadow: var(--shadow-overlay);
}

[data-theme="citadel"] .gs-dialog-content,
[data-theme="citadel"] .gs-sheet-content {
  font-family: var(--font-body);
}

[data-theme="citadel"] .gs-tooltip-content {
  background: oklch(var(--surface-raised));
  color: oklch(var(--foreground));
  border: 1px solid oklch(var(--border-strong) / 0.35);
  border-radius: var(--radius-control);
  font-family: var(--font-mono);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

[data-theme="citadel"] .gs-toaster [data-sonner-toast],
[data-theme="citadel"] .gs-toaster .toast {
  background: oklch(var(--surface) / 0.92) !important;
  border-color: oklch(var(--border-strong) / 0.3) !important;
  border-radius: var(--radius-control) !important;
  backdrop-filter: blur(var(--panel-blur));
}

/* -------------------------------------------------------------------------- */
/* Progress / Skeleton / Spinner                                              */
/* -------------------------------------------------------------------------- */

[data-theme="citadel"] .gs-progress {
  background: oklch(var(--surface-subtle));
  border: 1px solid oklch(var(--border-strong) / 0.18);
  border-radius: 0;
  overflow: hidden;
}

[data-theme="citadel"] .gs-progress-indicator {
  background: oklch(var(--primary));
  box-shadow: 0 0 10px oklch(var(--primary) / 0.4);
}

[data-theme="citadel"] .gs-skeleton {
  background: oklch(var(--surface-raised));
  border-radius: var(--radius-control);
  background-image: linear-gradient(
    90deg,
    oklch(var(--surface-raised)),
    oklch(var(--border-strong) / 0.12),
    oklch(var(--surface-raised))
  );
  background-size: 200% 100%;
  animation: gs-citadel-skeleton 1.4s var(--ease-standard) infinite;
}

@keyframes gs-citadel-skeleton {
  0% {
    background-position: 100% 0;
  }
  100% {
    background-position: -100% 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  [data-theme="citadel"] .gs-skeleton {
    animation: none;
    background-image: none;
  }
}

/* Multi-arc HUD spinner — hide lucide paths, draw concentric rings */
[data-theme="citadel"] .gs-spinner {
  position: relative;
  display: inline-block;
  color: transparent !important;
  animation: none !important;
}

[data-theme="citadel"] .gs-spinner > * {
  display: none;
}

[data-theme="citadel"] .gs-spinner::before,
[data-theme="citadel"] .gs-spinner::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 2px solid transparent;
  box-sizing: border-box;
}

[data-theme="citadel"] .gs-spinner::before {
  border-top-color: oklch(var(--primary));
  border-right-color: oklch(var(--primary));
  border-bottom-color: oklch(var(--primary));
  animation: gs-citadel-spinner-spin 1200ms linear infinite;
}

[data-theme="citadel"] .gs-spinner::after {
  inset: 18%;
  border-top-color: oklch(var(--primary) / 0.6);
  border-right-color: oklch(var(--primary) / 0.6);
  animation: gs-citadel-spinner-spin-reverse 1600ms linear infinite;
}

@keyframes gs-citadel-spinner-spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes gs-citadel-spinner-spin-reverse {
  to {
    transform: rotate(-360deg);
  }
}

@keyframes gs-citadel-spinner-pulse {
  0%,
  100% {
    opacity: 0.45;
    transform: scale(0.85);
  }
  50% {
    opacity: 1;
    transform: scale(1);
  }
}

@media (prefers-reduced-motion: reduce) {
  [data-theme="citadel"] .gs-spinner::before,
  [data-theme="citadel"] .gs-spinner::after {
    animation: none;
    border: none;
  }

  [data-theme="citadel"] .gs-spinner::before {
    inset: 30%;
    border-radius: 50%;
    background: oklch(var(--primary));
    box-shadow: var(--glow-pacific);
    animation: gs-citadel-spinner-pulse 1600ms ease-in-out infinite;
  }
}

/* -------------------------------------------------------------------------- */
/* Display / mono / connection                                                */
/* -------------------------------------------------------------------------- */

[data-theme="citadel"] .gs-display {
  font-family: var(--font-display);
  font-weight: var(--font-weight-heading);
  letter-spacing: var(--tracking-heading);
  line-height: 1.05;
}

[data-theme="citadel"][data-context="shared-display"] .gs-display {
  color: oklch(var(--primary));
  text-shadow: var(--glow-pacific-strong);
}

[data-theme="citadel"] .gs-mono {
  font-family: var(--font-mono);
  font-weight: 700;
  letter-spacing: 0.18em;
  font-variant-numeric: tabular-nums;
  color: oklch(var(--foreground));
}

[data-theme="citadel"][data-context="shared-display"] .gs-mono {
  color: oklch(var(--primary));
  text-shadow: var(--glow-pacific);
}

[data-theme="citadel"] .gs-connection-marker {
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 9999px;
  box-shadow: 0 0 8px currentColor;
}

/* -------------------------------------------------------------------------- */
/* Shells — grid + vignette + sticky action bar                               */
/* -------------------------------------------------------------------------- */

[data-theme="citadel"] .gs-shell {
  position: relative;
  isolation: isolate;
}

[data-theme="citadel"] .gs-shell::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background-image: var(--shell-vignette);
}

/* Participant — Pacific dot grid @ 30% opacity of audit 0.18 → use token */
[data-theme="citadel"][data-context="participant"] .gs-shell::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  opacity: 0.3;
  background-image: radial-gradient(
    circle,
    oklch(var(--shell-grid-color) / var(--shell-grid-dot-alpha)) 1px,
    transparent 1px
  );
  background-size: var(--shell-grid-size-participant) var(--shell-grid-size-participant);
}

[data-theme="citadel"][data-context="facilitator"] .gs-shell::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  opacity: 0.45;
  background-image: radial-gradient(
    circle,
    oklch(var(--shell-grid-color) / 0.028) 1px,
    transparent 1px
  );
  background-size: 48px 48px;
}

/* Shared display — line grid + dots + scanlines (static; no animated scan band) */
[data-theme="citadel"][data-context="shared-display"] .gs-shell::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background-image:
    linear-gradient(oklch(0.957 0.017 248 / var(--shell-grid-line-alpha)) 1px, transparent 1px),
    linear-gradient(
      90deg,
      oklch(0.957 0.017 248 / var(--shell-grid-line-alpha)) 1px,
      transparent 1px
    ),
    radial-gradient(circle, oklch(var(--shell-grid-color) / 0.18) 1px, transparent 1px),
    repeating-linear-gradient(
      0deg,
      transparent 0 3px,
      oklch(0.957 0.017 248 / var(--shell-scanline-alpha)) 3px 4px
    );
  background-size:
    200px 200px,
    200px 200px,
    var(--shell-grid-size-display) var(--shell-grid-size-display),
    100% 4px;
  opacity: 1;
}

[data-theme="citadel"] .gs-shell > * {
  position: relative;
  z-index: 1;
}

[data-theme="citadel"] .gs-shell-footer {
  position: sticky;
  bottom: 0;
  z-index: 2;
  margin-top: auto;
  padding-top: var(--action-bar-pad-top);
  background-image: var(--action-bar-bleed);
}
